The following code example shows how to enumerate ACEs using IADsAccessControlList::get__NewEnum.
HRESULT ListTrustees(IADsAccessControlList *pACL)
{
IEnumVARIANT *pEnum = NULL;
LPUNKNOWN pUnk = NULL;
ULONG lFetch = 0;
BSTR bstr = NULL;
IADsAccessControlEntry *pACE = NULL;
IDispatch *pDisp = NULL;
VARIANT var;
HRESULT hr = S_OK;
VariantInit(&var);
hr = pACL->get__NewEnum(&pUnk);
if (FAILED(hr)){goto Cleanup;}
hr = pUnk->QueryInterface( IID_IEnumVARIANT, (void**) &pEnum );
pUnk->Release();
if (FAILED(hr)){goto Cleanup;}
hr = pEnum->Next( 1, &var, &lFetch );
if (FAILED(hr)){goto Cleanup;}
while( hr == S_OK )
{
if ( lFetch == 1 )
{
if ( VT_DISPATCH != V_VT(&var) )
{
goto Cleanup;
}
pDisp = V_DISPATCH(&var);
/////////////////////////
// Get the individual ACE
/////////////////////////
hr = pDisp->QueryInterface( IID_IADsAccessControlEntry,(void**)&pACE );
if ( SUCCEEDED(hr) )
{
pACE->get_Trustee(&bstr);
printf("\n %S:\n", bstr);
//ACE manipulation here
SysFreeString(bstr);
pACE->Release();
}
pACE->Release();
pDisp->Release();
VariantClear(&var);
}
hr = pEnum->Next( 1, &var, &lFetch );
}
Cleanup:
if(pEnum) pEnum->Release();
if(pUnk) pUnk->Release();
if(bstr) SysFreeString(bstr);
if(pACE) pACE->Release();
VariantClear(&var);
return hr;
}
